def clean(df):
    df = df.copy()
    s = df["body_mass_g"].astype(str).str.replace(",", "", regex=False).str.strip()
    df["body_mass_g"] = pd.to_numeric(s, errors="coerce")
    df.loc[(df["body_mass_g"] < 2500) | (df["body_mass_g"] > 6500), "body_mass_g"] = float("nan")
    return df

def answer(df):
    g = df.dropna(subset=["species", "body_mass_g"]).groupby("species")["body_mass_g"].mean()
    return {k: float(v) for k, v in g.items()}
